  "691. 一、四类官方奖学金：条件 / 时间 / 差异对比（背诵重点）",
  "692. 记忆口诀：国奖、省奖＝拼成绩综合、不管穷不穷；国励、省励＝必须先困难认定、品学兼优；励志类两项不可兼得",
  "693. 同一学年内，获得国家奖学金／省政府奖学金／国家励志奖学金／省政府励志奖学金其中一项的学生，不能再申请其余三项（可同时申请国家助学金）",
  "694. 国家奖学金管理实施细则：228—231页（条件见第228—229页、标准见229页、评审程序见230页）",
  "695. 省政府奖学金管理实施细则：232—235页",
