  "697. 省政府励志奖学金管理实施细则：240—243页",
  "698. 二、社会奖助学金（书内第244—246页）",
  "699. 来源：企事业单位、社会团体、友好人士捐赠设立；命名按捐赠者意愿为\"山东航空学院××奖学金（助学金）\"",
  "700. 奖励对象：社会奖学金＝全日制本专科2年级以上学生；社会助学金＝品学兼优的家庭经济困难学生",
  "701. 基本条件（244—245页）：热爱祖国、遵纪守法、诚实守信、成绩优良、勤俭自强、积极参加社会实践与公益活动等；申请社会助学金必须为认定的家庭经济困难学生",
  "702. 优先条件（245页）：原建档立卡、特困供养人员/孤儿、低保家庭、特困城镇家庭子女、困难残疾学生、重病致困、烈士优抚家庭子女、突发重大变故致困等",
