  "706. （一）认定档次与比例（第248—249页）",
  "707. 分3档：特殊困难（A，3档）、困难（B，2档）、一般困难（C，1档）；总量控制在学生总数30%以内",
  "708. 特殊困难8类（248页）：原建档立卡、特困供养/孤儿、低保家庭、特困城镇家庭子女、困难残疾学生、重病致困、烈士优抚子女、突发重大变故致困",
  "709. 困难4类（248—249页）：父母务农或一方失业且医疗负担重、受灾损失重、单亲且父（母）无收入、其他原因",
  "710. 一般困难3类（249页）：基本生活费低于低保标准或校内平均消费、父母务农且两子女同时接受非义务教育、其他原因",
  "711. （二）不能认定的情形（第249页）",
  "712. 生活奢侈浪费（高档电子产品/时装/化妆品）、经常自费旅游、择校就读或自费出国、抽烟酗酒赌博、擅自外租民房或经常出入营业性网吧、因建房购房购车结婚经商致困、隐瞒家庭经济情况、与困难状况不符的高消费",
  "713. （三）认定流程（第250—251页，重点背诵）",
  "714. ①本人申请：如实填写《申请表》＋签署《认定承诺书》→交班级认定评议小组；上年已认定且无显著变化者不再提交承诺书",
