  "720. 每学年认定1次；信息库动态调整：突发变故可补充进库、经济好转应主动退出",
  "721. 四、新生入学\"绿色通道\"（书内第265—267页，与困难认定合并记忆）",
  "722. （一）适用对象（第265页）",
  "723. 被学校正式录取的全日制本专科新生，家庭经济困难、暂时交不起学费（可缓交全部或部分学费先办理入学手续）",
  "724. 可申请情形5类：烈士子女等优抚对象；孤儿、本人残疾且家庭经济困难；脱贫不稳定/边缘易致贫/城乡低保/特困救助/残疾人子女等特殊困难家庭；父母丧失劳动能力致困；近期遭重大自然灾害或突发事件致困",
  "725. （二）申请审批流程（第265—266页）",
  "726. ①新生申请：收到录取通知书后如实填写《家庭经济情况调查表》，附贫困资助申请书、录取通知书、身份证及复印件、乡（镇、街道）政府或原就读高中出具的困难证明，报到时递交学院",
  "727. ②学院审核：入学时设绿色通道服务站，登记审核材料，在《信息登记表》签意见报学生工作处",
  "728. ③学校审批：学生工作处复核审批通过后，新生持审批结果办理缓交学费入学手续，缴清除学费外其他费用",
  "729. （三）关键点（第266—267页）",
  "730. 原则应先行申请国家助学贷款解决学费；缓缴学费上限与当年国家助学贷款上限一致（全日制本专科生每人每年不超过20000元）",
  "731. 缓缴期限原则上不超过三个月；超过期限仍未缴清视作未完成本学年注册手续",
