  "734. 合并记忆逻辑：绿色通道＝新生报到阶段\"先入学、后缴费\"，入学后再补做困难认定；困难认定＝入学后走\"班级评议→学院公示→学校备案、建档\"程序，是励志奖学金、助学金、补助的基础门槛。绿色通道≠免学费",
  "735. 五、其他助学项目（简要了解，书内第254—279页）",
