  "737. 学费减免和困难补助：258—259页（学校每年从学费中提取一定比例经费，50%由二级学院掌握、50%由学生工作处掌握）",
  "738. 勤工助学：260—264页",
  "739. 生源地信用助学贷款：268—273页（入学前户籍与共同借款人户籍原则上同县；正常还息日每年12月20日）",
