  "742. 第四部分公寓管理（书内第280—306页，重点：卫生、违禁品）",
  "743. 一、学生公寓管理办法（书内第280—293页）",
  "744. （一）卫生管理（第283—284页）",
  "745. 室内卫生8项要求：空气清新无异味、阳台整洁无杂物",
  "746. 地面干净无划痕、墙面无乱贴乱画乱挂、无蛛网无球印脚印、垃圾及时清理",
  "747. 门窗玻璃窗帘灯具风扇完好洁净",
  "748. 家具定位摆放有序、无乱拉乱扯绳线",
  "749. 学习生活用品摆放有序",
  "750. 床上用品叠放符合军训标准、床下鞋子统一鞋跟向外由矮到高摆放",
