  "752. 宿舍文化格调高雅",
  "753. 值日制度：住宿人员轮流值日，值日生每日上午、下午上课前打扫，垃圾放到指定位置；每周二下午卫生大扫除；公寓管理人员周一至周五不定时检查内务",
  "754. 公共卫生由保洁人员负责：不随地吐痰，不向窗外、走廊、楼梯乱扔杂物泼污水",
