  "757. 严禁存放或使用违规电热器具：电炉、电冰箱、洗衣机、热得快、电饭锅、电热毯、电热杯等——没收用电器具＋纪律处分，酿成事故赔偿全部损失并追刑责",
  "758. 严禁私拉电线、私自安装插座接线装灯、加大灯泡或日光灯功率、擅自拆卸改造水电设施",
  "759. 宿舍内使用充电器具时房间内必须有人，否则没收并处分",
