  "761. 公寓内不允许圈养鸟、狗、猫、兔、鼠等宠物",
  "762. （三）秩序管理（第285—287页）",
  "763. 作息：早6点开门、晚22:30关门；熄灯时间——夏季24小时供电，冬季周日至周四23点熄灯、周5周六24点熄灯，早5点供电；晚归必须出示证件登记说明理由，严禁晚归或夜不归宿",
  "764. 男女生不准互访；不准留宿非本宿舍人员；来访人员登记，21时后不得会客",
  "765. 严禁赌博（打扑克、打麻将）、玩球类、溜冰、跳舞、弹奏打击乐器、使用大功率音响；不准带饭进公寓，杜绝聚餐、自炊",
  "766. 严禁大声吵闹喧哗、滋事起哄、打架斗殴、吸烟酗酒",
  "767. 严禁商贩进公寓经商；禁止张贴散发广告启事；贵重物品妥善保管，大额现金及时存银行",
  "768. （四）宿舍评比（第288—293页）",
  "769. 文明宿舍：精神风貌、学风、遵章守纪、安全文明、内务卫生五项",
