  "771. 优良学风宿舍：总体做到\"洁整美雅和\"",
  "772. 党员示范宿舍：政治素质过硬、道德素质良好、学习风气浓厚、内务卫生先进、党员作用突出",
  "773. 取消评选资格情形：一人次以上受校级通报批评或纪律处分、卫生不达标、晚归二人次以上、晚自习期间违纪通报",
  "774. 二、学生公寓文明公约（书内第294—295页）",
  "775. 安全防范：严禁私接电源、私拉室内网线",
  "776. 禁用电炉、电饭煲、电热杯（器）、电热毯、热得快等违禁电器",
  "777. 严禁易燃易爆、化学药品、易腐蚀品入公寓",
  "778. 宿舍内严禁点蜡烛、使用酒精炉煤油炉等明火",
  "779. 严禁攀爬公寓楼",
  "780. 严禁私自留宿外来人员，钥匙仅限本人使用不外借",
