  "1787. 教育实习目标：师范生在教育实习活动中了解教育教学工作实际，检验、巩固和提高自己所学的理论知识，掌握教学技能，初步具有独立从事教育教学实践和研究等能力，形成专业认同感，完成由师范生向一名准教师的转变",
