  "1833. 考核参考标准：教育见习考核指标分值评分个人见习计划。个人见习态度或考勤。班级工作。少先队工作。听课或课堂观察或儿童观察。评课或参加教研活动。批改作业。课外辅导。家访或家校联系。见习总结。得分等级",
  "1834. （1）教学工作实习参考考核标准考核项目课前准备课堂教学熟悉课程标准，熟练掌握教材的体系和重点、难点。备课独立处理教材，基于小学生的特点设计教学，方案（教学设计）完整。试教内容熟悉，教态自然，符合教学要求。试教认真、（教学模拟） 虚心。教学内容正确贯彻课程标准与教学原则，教学目的明确，重点突出，难点抓得准，思想性强，内容科学、系统。教学方法与组织启发性强，开展教学双边活动好。实验操作准确、熟练，注重培养学生动手能力。课堂教学组织严密，应变能力强。语言板书能用标准普通话教学，语言简洁、流畅、生动",
  "1835. 板书安排有序，文字工整、规范。教学效果课外辅导课后活动教学工作实习考核指标作业批改重视智能培养，顺利完成教学任务，达到教学目的，教学效果好。认真辅导质疑，答问正确。指导课外兴趣小组能力强。及时布置作业，分量适当，难易适度",
  "1836. 批改作业仔细、正确，评讲作业认真。分值评分考核项目实习态度教学工作实习考核指标听课评议积极参加听课和课后评议，敢于发表建设性意见。教学工作态度工作认真、虚心、踏实，授课后能认真做好自我分析小结。组织纪律性强，及时而有效地完成任务。分值评分分值评分得分等级",
  "1837. （2）班队工作实习参考考核标准考核项目工作准备工作内容和要求实习态度班队工作实习考核指标熟悉情况能较快地熟悉和掌握全班学生情况，班干部姓名和班级特点。制订计划能以党的教育思想为指导，根据学校和班级实际，制订切实可行的班主任工作实习计划。方法态度以身作则，积极配合原班主任开展工作，工作主动、认真，对学生既爱又严，态度诚恳。日常工作跟班参加班级的全部日常工作，妥善处理日常事务，善做学生的思想工作，关心学生生活，效果好。集体活动组织和辅导主题班会、班级活动、兴趣小组，内容丰富，适合学生特点，效果好。个别观察、指导与教育有针对性地了解个别学生的实际情况，作出个别指导与教育。善于处理偶发事件，效果好。家校联系善于运用家访、家长会或其他形式进行家校联系，取得家长密切配合，对学生开展教育，效果好。工作能力能独立开展工作，组织管理能力强。行为表率工作责任心强，为人师表，热爱学生，深受学生的尊敬和爱戴。工作小结对自己的工作能运用心理学、教育学的基本原理进行分析小结，在吸取经验教训的基础上，提出创造性见解。得分等级",
  "1838. 积极消化吸收师生同伴课前课后所提的意见与建议。课程研究参与或组织已有校本课程开发、实施与评价的案例研究",
  "1839. 结合实习内容认真研读学科课程标准。教育调查或行动研究教研成果研究主题明确、针对小学教育的实际问题。设计的方案周详、可操作性强。完成有一定价值的研究报告或论文。形成的教研报告或论文，思路清晰、内容丰富、见解深刻。得分等级",
